import{_ as i,C as e,o as l,c as n,E as a,a2 as o}from"./chunks/framework.BdWD-ld-.js";const u=JSON.parse('{"title":"精确率算对了，为什么报告仍可能没有证据？","description":"","frontmatter":{"title":"精确率算对了，为什么报告仍可能没有证据？","article_type":"engineering-insight","edition":"research-center","research_question":"代理报告中的数字，要绑定哪些证据才可用于验收？","summary":"数字的计算正确性与证据适用性是两道检查。论文中的轨迹归因案例、独立维护者的指标撤回记录和内部评分探针，共同提示验收者核对对象、分母、版本与时间角色。","sources":["https://arxiv.org/html/2611.25760v1","https://raw.githubusercontent.com/HeadyZhang/agent-audit/8c4c5cb9bddd4758b064577c912ee8afcaf5330f/docs/decisions/METRICS_RETRACTION.md","https://raw.githubusercontent.com/HeadyZhang/agent-audit/8c4c5cb9bddd4758b064577c912ee8afcaf5330f/docs/BENCHMARK-RESULTS.md","https://api.figshare.com/v2/articles/34056699"],"date":"2026-11-21","column":"digital-employee","category":"daily","pageClass":"runtime-v6-article","item_id":"SIG-20261121-005","lifecycle":"Published","cover":"/assets/covers/daily-2026-11-21-sig-20261121-005-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"zh/digital-employee/2026-11-21-sig-20261121-005.md","filePath":"zh/digital-employee/2026-11-21-sig-20261121-005.md","lastUpdated":1795263789000}'),s={name:"zh/digital-employee/2026-11-21-sig-20261121-005.md"};function h(c,t,g,p,b,m){const r=e("ArticleCover"),d=e("ArticleTableScroll");return l(),n("div",null,[a(r,{image:"/assets/covers/daily-2026-11-21-sig-20261121-005-cover.png",kicker:"研究成果",title:"精确率算对了，为什么报告仍可能没有证据？",summary:"数字的计算正确性与证据适用性是两道检查。论文中的轨迹归因案例、独立维护者的指标撤回记录和内部评分探针，共同提示验收者核对对象、分母、版本与时间角色。",version:"2026-11-21",languageHref:"/en/digital-employee/2026-11-21-sig-20261121-005",languageLabel:"English"}),a(d,{language:"zh"}),t[0]||(t[0]=o('<h1 id="精确率算对了-为什么报告仍可能没有证据" tabindex="-1">精确率算对了，为什么报告仍可能没有证据？ <a class="header-anchor" href="#精确率算对了-为什么报告仍可能没有证据" aria-label="Permalink to &quot;精确率算对了，为什么报告仍可能没有证据？&quot;">​</a></h1><p>测试通过，代码也推送成功，为什么“已完成交付”仍可能超出证据？一项代理工作报告研究重建的案例给出了具体原因：成功操作发生的仓库与分支，并不是用户请求中的合并请求所追踪的位置。另一案例用旧版本的健康部署状态支持当前交付判断。操作可以真实发生，报告仍可能指向错误对象。<a href="https://arxiv.org/html/2611.25760v1" target="_blank" rel="noreferrer">研究正文，案例 r6748、r4587</a></p><p>对验收代理工作的工程师，类似问题也藏在漂亮的百分比里。本文的判断是：<strong>数字只有绑定实际测量的对象、分母、版本和时间角色，才有资格支持相应验收结论。</strong> 算式正确可以核对计算，却不能补出没测过的漏报，也不能把历史结果搬到当前版本。</p><h2 id="成功动作与适用证据之间-还差一层对应关系" tabindex="-1">成功动作与适用证据之间，还差一层对应关系 <a class="header-anchor" href="#成功动作与适用证据之间-还差一层对应关系" aria-label="Permalink to &quot;成功动作与适用证据之间，还差一层对应关系&quot;">​</a></h2><p>上述论文研究报告中的主张是否得到报告生成前轨迹的支持。它报告，在抽样的 435 份报告中，162 份存在失实主张，即 37.24%。这个分母是抽样报告，不是所有代理任务；会话级抽样使报告被纳入的概率不等，未解决或未提取的主张也限制了外推。这里引用的是作者报告的研究结果，我们没有重新构建这些事故或标注原始轨迹。<a href="https://arxiv.org/html/2611.25760v1" target="_blank" rel="noreferrer">研究方法与限制</a></p><p>错误的共同机制是“证据存在”被替换成“证据适用于这句话”。一条成功推送记录需要连接到目标仓库、分支与修订；一个部署健康结果需要连接到被交付版本。对数字而言，同一对应关系还要包含数据集、评分程序和分母。完整的对应关系比更多成功日志更重要，这是我们对这些案例的工程解释。</p><p>第二组来源来自独立作者维护的代理审计项目。其固定提交中的指标撤回记录称，漏报数曾被假定为零，目标值曾进入变更记录成为已实现指标；同文引用的已提交结果却有 112 个正确检出、4 个误报和 124 个漏报。这里的历史取证仍是维护者自述，我们没有重跑其历史命令。它与论文不共享作者或测量过程，也没有复现论文的检测器；它支持的是另一种独立发生的证据归属问题。<a href="https://raw.githubusercontent.com/HeadyZhang/agent-audit/8c4c5cb9bddd4758b064577c912ee8afcaf5330f/docs/decisions/METRICS_RETRACTION.md" target="_blank" rel="noreferrer">固定版本撤回记录</a></p><h2 id="把分母换掉-精确率可以纹丝不动" tabindex="-1">把分母换掉，精确率可以纹丝不动 <a class="header-anchor" href="#把分母换掉-精确率可以纹丝不动" aria-label="Permalink to &quot;把分母换掉，精确率可以纹丝不动&quot;">​</a></h2><p>精确率回答“报出的阳性里有多少正确”，召回率回答“全部真实阳性里找到了多少”。前者只需要正确检出与误报，后者还必须知道漏报。只保存命中记录，无法由此算出完整召回率。</p><p>此前完成的内部探针，从作者公开评分脚本中提取评分函数，固定正确检出 421、误报 42、正确阴性 1830，只人为改变漏报数。下表是该内部敏感性计算的节选，不是新测出的检测器表现。<a href="https://api.figshare.com/v2/articles/34056699" target="_blank" rel="noreferrer">公开评分材料</a>；<a href="/joinwell52/assets/evidence/2026-11-21-sig-20261121-005/metric-probe.json">内部探针数值节选</a></p><table tabindex="0"><thead><tr><th>输入情形</th><th style="text-align:right;">漏报数</th><th style="text-align:right;">精确率</th><th style="text-align:right;">召回率</th></tr></thead><tbody><tr><td>作者矩阵作为计算对照</td><td style="text-align:right;">63</td><td style="text-align:right;">90.93%</td><td style="text-align:right;">86.98%</td></tr><tr><td>人为增加 63 个漏报</td><td style="text-align:right;">126</td><td style="text-align:right;">90.93%</td><td style="text-align:right;">76.97%</td></tr><tr><td>人为增加 124 个漏报</td><td style="text-align:right;">187</td><td style="text-align:right;">90.93%</td><td style="text-align:right;">69.24%</td></tr></tbody></table><p>例如，对照的精确率为 421÷(421+42)，召回率为 421÷(421+63)。新增漏报后，前一个算式完全不变。这不是说论文遗漏了表中的那些漏报，而是一个反例：<strong>相同精确率可以对应不同召回率，因此精确率本身不能补全未知分母。</strong> 论文、附件与存储平台属于同一个作者来源；我们的算术探针属于内部实验，都不额外增加独立来源数量。</p><p>这种检查适用于审阅“找到了多少问题”被写成“找全了多少问题”的报告。不适用于把所有不可观测项目直接算作错误：未标注、未提取、无法判定和真实漏报是不同状态，不能为了算出一个分数强行合并。</p><h2 id="历史数字与当前数字不能共享一个免责范围" tabindex="-1">历史数字与当前数字不能共享一个免责范围 <a class="header-anchor" href="#历史数字与当前数字不能共享一个免责范围" aria-label="Permalink to &quot;历史数字与当前数字不能共享一个免责范围&quot;">​</a></h2><p>维护者还描述过一个修复中的矛盾：整篇文档被加入历史引用豁免后，确实保住了旧引文，却也隐藏了同文中仍应更新的当前指标。因此，时间角色至少需要区分历史实测、当前实测和目标。保留历史不意味着当前段落可以继续使用过期数值。<a href="https://raw.githubusercontent.com/HeadyZhang/agent-audit/8c4c5cb9bddd4758b064577c912ee8afcaf5330f/docs/decisions/METRICS_RETRACTION.md" target="_blank" rel="noreferrer">撤回记录</a></p><p>固定版本文件自身也没有完全对齐：撤回记录第 3 节给出正确检出 199、误报 90、漏报 37 及综合分数 0.7581，第 3a 节替换表首行仍保留 0.7467，后文草案仍有旧版表述。配套基准文档把历史结果与当前 81 个样本的夹具说明分开。不能把所有替换数字都视为同一次当前测量，也不能仅凭分数下降就断言检测能力退步；维护者对文件发现范围与标签修复的解释仍需按其原范围引用。<a href="https://raw.githubusercontent.com/HeadyZhang/agent-audit/8c4c5cb9bddd4758b064577c912ee8afcaf5330f/docs/BENCHMARK-RESULTS.md" target="_blank" rel="noreferrer">基准记录</a></p><h2 id="验收时-让每个数字带着它能支持的范围" tabindex="-1">验收时，让每个数字带着它能支持的范围 <a class="header-anchor" href="#验收时-让每个数字带着它能支持的范围" aria-label="Permalink to &quot;验收时，让每个数字带着它能支持的范围&quot;">​</a></h2><p>下面是一项审阅建议，不是已经部署并证实有效的系统。可以把每个重要数字视为一条关系记录，再决定是否接受其结论：</p><table tabindex="0"><thead><tr><th>检查位置</th><th>接受前需要回答的问题</th><th>缺失时保留什么</th></tr></thead><tbody><tr><td>对象与目的地</td><td>哪个制品、仓库、分支或部署？</td><td>目标归属未确认</td></tr><tr><td>数据与分母</td><td>哪批样本、纳入排除规则、漏报如何得知？</td><td>覆盖范围未知</td></tr><tr><td>版本与计算</td><td>哪份输入、哪个评分程序、哪次修订？</td><td>可追溯性不足</td></tr><tr><td>时间角色</td><td>历史实测、当前实测，还是目标？</td><td>时间适用性未确认</td></tr><tr><td>支持范围</td><td>证据支持整句主张，还是其中一部分？</td><td>区分支持缺口与直接矛盾</td></tr></tbody></table><p>一个贯穿例子是“当前版本已达到目标召回率”。报告生成者应提交实际测量记录与版本绑定；评分程序负责按确定输入计算；验收者负责检查分母和适用范围；文档维护者负责保留旧测量的历史身份。若只有命中列表，验收者可以确认这些命中，不能把未测漏报填零并接受目标已达成。若数字只适用于旧版，则保留旧记录并要求当前证据，而非改写历史。</p><h2 id="更严格的核对-也可能制造误报" tabindex="-1">更严格的核对，也可能制造误报 <a class="header-anchor" href="#更严格的核对-也可能制造误报" aria-label="Permalink to &quot;更严格的核对，也可能制造误报&quot;">​</a></h2><p>论文提供了重要反例：在 n120 案例中，检测器因缺少安装后的文件观察而质疑锁文件生成，但人工标注和基线接受了“原先不存在该文件且安装成功”所支持的常规副作用。对每件事都要求额外截图，可能拒绝合理推断，而不是提高真实性。<a href="https://arxiv.org/html/2611.25760v1" target="_blank" rel="noreferrer">论文反例与讨论</a></p><p>因此，前述关系记录应帮助定位适用证据，而非要求每一步都有同一种证明形式。直接冲突、证据不足与合理的机制推断需要不同处置。论文的配对检测评测也限定在可判定主张与相同报告材料中；它没有直接回答这套审阅建议能否减少人工监督时间。维护者的撤回与修复记录同样不能给出预防效果。</p><p>下一步可验证的问题是：在同一批固定报告上，预先定义验收规则，并与现有审阅方式比较漏掉的越界主张、误报和实际审阅时间。该验证尚未执行。当前可以采用的是检查问题和对未知项的保留方式，而不是一个已经证实改善交付的效果承诺。</p>',24))])}const _=i(s,[["render",h]]);export{u as __pageData,_ as default};
